# Usage (racine du repo) : bash apply-docs-avatars.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/stockage/lire-l-arbre.mdx" 2>/dev/null | grep -qF "Les avatars n’en font pas partie"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "assertOutsideAvatars" "packages/backend/src/modules/storage/mediaPaths.ts" 2>/dev/null || { echo "❌ lancer d'abord apply-fix-avatars.sh"; exit 1; }
grep -qF "isPubliclyPlaced" "apps/web/content/docs/dev/contenu/le-recensement-des-fichiers.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-docs-brouillons.sh"; exit 1; }
