sub('apps/web/content/docs/dev/stockage/modifier-sans-casser.mdx', '',
    '')
sub('apps/web/content/docs/dev/stockage/modifier-sans-casser.mdx', 'ICBmaWxlcGF0aD0icGFja2FnZXMvYmFja2VuZC9zcmMvbW9kdWxlcy9zdG9yYWdlL21lZGlhUGF0aHMudHMiCiAgZmlsZW5hbWU9Im1lZGlhUGF0aHMudHMiCiAgc25pcHBldFJhbmdlPSIyMy00MyIKICBzbmlwcGV0SGlnaGxpZ2h0PSIxNSwxOCIKICBzbmlwcGV0VGl0bGU9InJld3JpdGVBc3NldFBhdGhzIgo=',
    'ICBmaWxlcGF0aD0icGFja2FnZXMvYmFja2VuZC9zcmMvbW9kdWxlcy9zdG9yYWdlL21lZGlhUGF0aHMudHMiCiAgZmlsZW5hbWU9Im1lZGlhUGF0aHMudHMiCiAgc25pcHBldFJhbmdlPSIyNC00NCIKICBzbmlwcGV0SGlnaGxpZ2h0PSIxNSwxOCIKICBzbmlwcGV0VGl0bGU9InJld3JpdGVBc3NldFBhdGhzIgo=')
