sub('apps/web/content/docs/dev/stockage/signer-un-envoi.mdx', 'ICBmaWxlcGF0aD0icGFja2FnZXMvYmFja2VuZC9zcmMvbW9kdWxlcy9zdG9yYWdlL3JvdXRlci50cyIKICBmaWxlbmFtZT0icm91dGVyLnRzIgogIHNuaXBwZXRSYW5nZT0iODQzLTg2OCIKICBzbmlwcGV0SGlnaGxpZ2h0PSIxOCwyMyIKICBzbmlwcGV0VGl0bGU9ImNoZWNrUjJDb25mbGljdHMiCg==',
    'ICBmaWxlcGF0aD0icGFja2FnZXMvYmFja2VuZC9zcmMvbW9kdWxlcy9zdG9yYWdlL3JvdXRlci50cyIKICBmaWxlbmFtZT0icm91dGVyLnRzIgogIHNuaXBwZXRSYW5nZT0iODU5LTg4NCIKICBzbmlwcGV0SGlnaGxpZ2h0PSIxOCwyMyIKICBzbmlwcGV0VGl0bGU9ImNoZWNrUjJDb25mbGljdHMiCg==')
